            Add("enc.wreck_signal_trap.approach", "그대로 접근한다 (55%)", "Approach directly (55%)");
            Add("enc.wreck_signal_trap.approach.r", "진짜 생존자였습니다. 50명이 합류했습니다.", "The call was real. Fifty survivors join you.");
            Add("enc.wreck_signal_trap.ambush", "매복", "Ambush");
            Add("enc.wreck_signal_trap.ambush.r", "난파선 뒤에서 제국 커터가 튀어나옵니다!", "An imperial cutter bursts from behind the wreck!");
