            Add("enc.derelict_cruiser.strip.r", "군수품과 부품을 확보했습니다.", "Ordnance and parts secured.");
            Add("enc.derelict_cruiser.core", "[드워프] 코어를 추출한다 (70%)", "[Dwarf] Extract the core (70%)");
            Add("enc.derelict_cruiser.core.r", "코어가 안전하게 빠져나왔습니다.", "The core comes free cleanly.");
            Add("enc.derelict_cruiser.core_fail", "코어 폭주", "Core surge");
            Add("enc.derelict_cruiser.core_fail.r", "코어가 폭주하며 선체를 태웠습니다.", "The core surges and scorches the hull.");
            Add("enc.derelict_cruiser.leave", "손대지 않는다", "Leave it");
            Add("enc.derelict_cruiser.leave.r", "순양함은 계속 표류합니다.", "The cruiser drifts on.");
            Add("enc.aether_geyser.title", "에테르 간헐천", "THE AETHER GEYSER");
